func migrationAgree(base, staged string) bool {
	baseOutside, baseMarkers, ok := splitRegions(base)
	if !ok {
		return false
	}
	if len(baseMarkers) == 0 {
		return false
	}
	stagedOutside, stagedMarkers, ok := splitRegions(staged)
	if !ok {
		return false
	}
	if baseOutside != stagedOutside {
		return false
	}
	if len(baseMarkers) != len(stagedMarkers) {
		return false
	}
	for i := range baseMarkers {
		b := baseMarkers[i]
		s := stagedMarkers[i]
		if b.Tier != s.Tier || b.Record != s.Record || b.Gen != s.Gen || b.Pkg != s.Pkg {
			return false
		}
		if b.Prefix != s.Prefix || b.Body != s.Body || b.Close != s.Close {
			return false
		}
	}
	return true
}

